      ByteArrayOutputStream reel = new ByteArrayOutputStream();
      for (String line : Files.readAllLines(manifest)) {
        String key = line.trim();
        if (key.isEmpty()) continue;
        String rel = idx.get(key);
        if (rel == null) throw new IOException("missing silo key " + key);
        reel.write(Idx.blob(rel));
      }

      List<byte[]> parts = Slice.cut(reel.toByteArray(), g.mask, g.min, g.max);
      StringBuilder rewritten = new StringBuilder();
